import re
from collections import defaultdict
from decimal import ROUND_HALF_UP, Decimal
from itertools import combinations

CENT = Decimal("0.01")
_MONTH_RE = re.compile(r"([0-9]{4})-([0-9]{2})")


def parse_month(month):
    """Parse 'YYYY-MM' into (year, month) ints. Raises ValueError if malformed."""
    m = _MONTH_RE.fullmatch(month)
    if m is None or not 1 <= int(m.group(2)) <= 12:
        raise ValueError(f"invalid month {month!r}: expected YYYY-MM")
    return int(m.group(1)), int(m.group(2))


def filter_month(transactions, month):
    """Return the transactions dated in the calendar month given as 'YYYY-MM'."""
    year, mon = parse_month(month)
    return [t for t in transactions if t.day.year == year and t.day.month == mon]


def _cents(amount):
    return Decimal(str(amount)).quantize(CENT, rounding=ROUND_HALF_UP)


def summarize(transactions, month):
    """Map category -> net total for the month (rounded to cents), omitting zero totals."""
    totals = defaultdict(Decimal)
    for t in filter_month(transactions, month):
        totals[t.category] += Decimal(str(t.amount))
    result = {}
    for category, total in totals.items():
        rounded = _cents(total)
        if rounded != 0:
            result[category] = float(rounded)
    return result


def find_duplicates(transactions):
    """Return (earlier_id, later_id) for same-payee, same-amount pairs at most 2 days apart.

    Negative amounts (refunds) are never considered. Each unordered pair appears once,
    sorted by the earlier transaction's (day, id) then the later one's (day, id).
    """
    by_payee = defaultdict(list)
    for t in transactions:
        if t.amount < 0:
            continue
        by_payee[t.payee].append(t)

    pairs = []
    for group in by_payee.values():
        for a, b in combinations(group, 2):
            if _cents(a.amount) != _cents(b.amount):
                continue
            if abs((a.day - b.day).days) > 2:
                continue
            earlier, later = sorted((a, b), key=lambda t: (t.day, t.id))
            pairs.append((earlier, later))

    pairs.sort(key=lambda p: (p[0].day, p[0].id, p[1].day, p[1].id))
    return [(earlier.id, later.id) for earlier, later in pairs]

