import json
import subprocess
import sys
from datetime import date
from pathlib import Path

import pytest

PROJECT_DIR = Path(__file__).resolve().parent.parent
if str(PROJECT_DIR) not in sys.path:
    sys.path.insert(0, str(PROJECT_DIR))

from ledger.models import Transaction  # noqa: E402
from ledger.report import filter_month, find_duplicates, parse_month, summarize  # noqa: E402


def tx(id, day, payee="P", category="C", amount=1.0):
    return Transaction(id=id, day=date.fromisoformat(day), payee=payee, category=category, amount=amount)


# ---------------------------------------------------------------- filter_month


def test_filter_month_boundary_days():
    txs = [
        tx("a", "2026-09-30"),
        tx("b", "2026-10-01"),
        tx("c", "2026-10-31"),
        tx("d", "2026-11-01"),
    ]
    assert [t.id for t in filter_month(txs, "2026-10")] == ["b", "c"]


def test_filter_month_excludes_same_month_other_year():
    txs = [tx("a", "2025-10-15"), tx("b", "2026-10-15")]
    assert [t.id for t in filter_month(txs, "2026-10")] == ["b"]


def test_parse_month_valid():
    assert parse_month("2026-10") == (2026, 10)


@pytest.mark.parametrize("bad", ["2026-13", "2026-00", "2026-1", "26-10", "2026/10", "October", ""])
def test_parse_month_invalid(bad):
    with pytest.raises(ValueError):
        parse_month(bad)


# ---------------------------------------------------------------- summarize


def test_summarize_only_requested_month():
    txs = [
        tx("a", "2026-09-30", category="Housing", amount=900),
        tx("b", "2026-10-01", category="Housing", amount=900),
        tx("c", "2026-11-01", category="Housing", amount=900),
    ]
    assert summarize(txs, "2026-10") == {"Housing": 900.0}


def test_summarize_refund_reduces_total():
    txs = [
        tx("a", "2026-10-03", category="Groceries", amount=54.20),
        tx("b", "2026-10-04", category="Groceries", amount=54.20),
        tx("c", "2026-10-12", category="Groceries", amount=-10.0),
    ]
    assert summarize(txs, "2026-10") == {"Groceries": 98.4}


def test_summarize_float_drift_0_1_plus_0_2():
    txs = [
        tx("a", "2026-10-01", category="Misc", amount=0.1),
        tx("b", "2026-10-02", category="Misc", amount=0.2),
    ]
    result = summarize(txs, "2026-10")
    assert result == {"Misc": 0.3}


def test_summarize_float_drift_many_small_amounts():
    txs = [tx(str(i), "2026-10-05", category="Misc", amount=0.1) for i in range(10)]
    assert summarize(txs, "2026-10") == {"Misc": 1.0}


def test_summarize_rounds_to_two_decimals():
    txs = [
        tx("a", "2026-10-01", category="Fun", amount=19.99),
        tx("b", "2026-10-02", category="Fun", amount=19.99),
        tx("c", "2026-10-03", category="Fun", amount=19.99),
    ]
    assert summarize(txs, "2026-10") == {"Fun": 59.97}


def test_summarize_result_has_at_most_two_decimals():
    txs = [tx("a", "2026-10-01", category="Fun", amount=0.333), tx("b", "2026-10-02", category="Fun", amount=0.333)]
    result = summarize(txs, "2026-10")
    assert result == {"Fun": 0.67}


def test_summarize_omits_category_netting_to_zero():
    txs = [
        tx("a", "2026-10-01", category="Groceries", amount=10.0),
        tx("b", "2026-10-02", category="Groceries", amount=-10.0),
        tx("c", "2026-10-03", category="Fun", amount=5.0),
    ]
    result = summarize(txs, "2026-10")
    assert "Groceries" not in result
    assert result == {"Fun": 5.0}


def test_summarize_omits_float_drift_zero_net():
    txs = [
        tx("a", "2026-10-01", category="Misc", amount=0.1),
        tx("b", "2026-10-02", category="Misc", amount=0.2),
        tx("c", "2026-10-03", category="Misc", amount=-0.3),
    ]
    assert summarize(txs, "2026-10") == {}


def test_summarize_empty_month():
    txs = [tx("a", "2026-09-01", category="Fun", amount=5.0)]
    assert summarize(txs, "2026-10") == {}


# ---------------------------------------------------------------- find_duplicates


def test_duplicates_same_day_pair():
    txs = [tx("t1", "2026-10-03", payee="Shop", amount=20.0), tx("t2", "2026-10-03", payee="Shop", amount=20.0)]
    assert find_duplicates(txs) == [("t1", "t2")]


def test_duplicates_two_days_apart_included():
    txs = [tx("t1", "2026-10-03", payee="Shop", amount=20.0), tx("t2", "2026-10-05", payee="Shop", amount=20.0)]
    assert find_duplicates(txs) == [("t1", "t2")]


def test_duplicates_three_days_apart_excluded():
    txs = [tx("t1", "2026-10-03", payee="Shop", amount=20.0), tx("t2", "2026-10-06", payee="Shop", amount=20.0)]
    assert find_duplicates(txs) == []


def test_duplicates_different_payee_excluded():
    txs = [tx("t1", "2026-10-03", payee="Shop A", amount=20.0), tx("t2", "2026-10-03", payee="Shop B", amount=20.0)]
    assert find_duplicates(txs) == []


def test_duplicates_different_amount_excluded():
    txs = [tx("t1", "2026-10-03", payee="Shop", amount=20.0), tx("t2", "2026-10-03", payee="Shop", amount=20.01)]
    assert find_duplicates(txs) == []


def test_duplicates_refunds_never_duplicates():
    txs = [tx("r1", "2026-10-03", payee="Shop", amount=-10.0), tx("r2", "2026-10-03", payee="Shop", amount=-10.0)]
    assert find_duplicates(txs) == []


def test_duplicates_refund_and_purchase_not_paired():
    txs = [tx("p1", "2026-10-03", payee="Shop", amount=10.0), tx("r1", "2026-10-03", payee="Shop", amount=-10.0)]
    assert find_duplicates(txs) == []


def test_duplicates_ordering_earlier_first_even_when_input_reversed():
    later = tx("t2", "2026-10-05", payee="Shop", amount=20.0)
    earlier = tx("t1", "2026-10-03", payee="Shop", amount=20.0)
    assert find_duplicates([later, earlier]) == [("t1", "t2")]


def test_duplicates_same_day_pair_ordered_by_id_when_input_reversed():
    txs = [tx("t2", "2026-10-03", payee="Shop", amount=20.0), tx("t1", "2026-10-03", payee="Shop", amount=20.0)]
    assert find_duplicates(txs) == [("t1", "t2")]


def test_duplicates_list_sorted_by_earlier_date_then_id():
    txs = [
        tx("c", "2026-10-10", payee="X", amount=5.0),
        tx("d", "2026-10-11", payee="X", amount=5.0),
        tx("b", "2026-10-02", payee="Y", amount=7.0),
        tx("a", "2026-10-01", payee="Y", amount=7.0),
        tx("e", "2026-10-01", payee="Z", amount=9.0),
        tx("f", "2026-10-01", payee="Z", amount=9.0),
    ]
    result = find_duplicates(txs)
    assert result == [("a", "b"), ("e", "f"), ("c", "d")]


def test_duplicates_sorted_by_id_for_same_earlier_date():
    txs = [
        tx("z1", "2026-10-01", payee="Q", amount=3.0),
        tx("z2", "2026-10-01", payee="Q", amount=3.0),
        tx("m1", "2026-10-01", payee="P", amount=4.0),
        tx("m2", "2026-10-01", payee="P", amount=4.0),
    ]
    result = find_duplicates(txs)
    assert result == [("m1", "m2"), ("z1", "z2")]


def test_duplicates_three_way_yields_all_pairs():
    txs = [
        tx("t1", "2026-10-01", payee="Shop", amount=12.0),
        tx("t2", "2026-10-02", payee="Shop", amount=12.0),
        tx("t3", "2026-10-03", payee="Shop", amount=12.0),
    ]
    result = find_duplicates(txs)
    assert sorted(result) == [("t1", "t2"), ("t1", "t3"), ("t2", "t3")]
    assert len(result) == 3


def test_duplicates_empty_input():
    assert find_duplicates([]) == []


# ---------------------------------------------------------------- CLI


def run_cli(*args):
    return subprocess.run(
        [sys.executable, "-m", "ledger", *args],
        cwd=PROJECT_DIR,
        capture_output=True,
        text=True,
    )


def test_cli_report_october_exact_output():
    proc = run_cli("report", "data.json", "--month", "2026-10")
    assert proc.returncode == 0, proc.stderr
    assert proc.stdout == "Housing: 900.00\nGroceries: 98.40\nTransport: 45.00\nFun: 37.00\nPossible duplicates: 1\n"


def test_cli_report_november_exact_output():
    proc = run_cli("report", "data.json", "--month", "2026-11")
    assert proc.returncode == 0, proc.stderr
    assert proc.stdout == "Housing: 900.00\nPossible duplicates: 0\n"


def test_cli_tie_sorted_by_category_name(tmp_path):
    data = [
        {"id": "1", "day": "2026-10-01", "payee": "A", "category": "Zeta", "amount": 10.0},
        {"id": "2", "day": "2026-10-02", "payee": "B", "category": "Alpha", "amount": 10.0},
        {"id": "3", "day": "2026-10-03", "payee": "C", "category": "Mid", "amount": 25.5},
    ]
    path = tmp_path / "ties.json"
    path.write_text(json.dumps(data), encoding="utf-8")
    proc = run_cli("report", str(path), "--month", "2026-10")
    assert proc.returncode == 0, proc.stderr
    assert proc.stdout == "Mid: 25.50\nAlpha: 10.00\nZeta: 10.00\nPossible duplicates: 0\n"


@pytest.mark.parametrize("bad", ["2026-13", "2026-1", "October", "2026-00"])
def test_cli_invalid_month_exits_nonzero(bad):
    proc = run_cli("report", "data.json", "--month", bad)
    assert proc.returncode != 0
